package org.example.level10_10;

import java.util.ArrayList;
import java.util.List;

public class ArrayPermutations {

    private static final int MAX_LENGTH = 8;

    /** All permutations of the array (n! of them), generated by recursive swapping. */
    public List<int[]> permute(int[] values) {
        if (values.length > MAX_LENGTH) {
            throw new IllegalArgumentException(
                    "Array is too long for permutations: " + values.length + " > " + MAX_LENGTH);
        }
        List<int[]> result = new ArrayList<>();
        walk(values.clone(), 0, result);
        return result;
    }

    /** Fixes every remaining element at position {@code index} in turn and permutes the rest. */
    private static void walk(int[] values, int index, List<int[]> result) {
        if (index == values.length) {
            result.add(values.clone());
            return;
        }
        for (int i = index; i < values.length; i++) {
            swap(values, index, i);
            walk(values, index + 1, result);
            swap(values, index, i);
        }
    }

    private static void swap(int[] values, int first, int second) {
        int temp = values[first];
        values[first] = values[second];
        values[second] = temp;
    }
}
